import pandas as pd
import numpy as np

# List of available experiment CSVs
csv_vars = [experiment_1_csv, experiment_3_csv, experiment_4_csv, experiment_5_csv, experiment_6_csv, experiment_7_csv, experiment_8_csv]

frames = []
for v in csv_vars:
    try:
        frames.append(pd.read_csv(v))
    except Exception:
        pass

if not frames:
    print("No data loaded.")
else:
    df = pd.concat(frames, ignore_index=True)
    print("Rows:", len(df), "Cols:", list(df.columns))

    # Identify numeric columns for quick correlation
    num_cols = df.select_dtypes(include='number').columns.tolist()
    if 'CapacityRetention' in num_cols:
        # Quick groupby on likely categorical/discrete controls
        for c in ['DryRoomControl', 'ChargeRate', 'CellCooling']:
            if c in df.columns:
                print(f"\nMean CapacityRetention by {c}:")
                print(df.groupby(c)['CapacityRetention'].agg(['mean', 'std', 'count']))

        # Correlations with top numeric cols
        top = ['CapacityRetention']
        for c in ['DryRoomControl', 'AmbientHumidityBatt', 'ChargeRate', 'CellCooling', 'CoulombicEfficiency', 'PackVoltage']:
            if c in num_cols and c != 'CapacityRetention':
                top.append(c)
        print("\nCorrelation with CapacityRetention:")
        print(df[top].corr(numeric_only=True)['CapacityRetention'])
